// Parse address into components for skip tracing

const lead = $input.first().json;
const address = lead.fields?.Address || lead.Address || '';

// Try to parse address into components
// Format expected: "123 Main St, Austin, TX 78701" or similar
const parts = address.split(',').map(p => p.trim());

let streetAddress = '';
let city = '';
let state = '';
let zip = '';

if (parts.length >= 1) {
  streetAddress = parts[0];
}

if (parts.length >= 2) {
  city = parts[1];
}

if (parts.length >= 3) {
  // State and ZIP might be together like "TX 78701"
  const stateZip = parts[2].split(' ').filter(p => p);
  if (stateZip.length >= 1) state = stateZip[0];
  if (stateZip.length >= 2) zip = stateZip[1];
}

// If we couldn't parse well, use defaults
if (!city) city = 'Austin'; // Change to your default city
if (!state) state = 'TX'; // Change to your default state

return [{
  json: {
    ...lead,
    parsedAddress: {
      street: streetAddress,
      city: city,
      state: state,
      zip: zip,
      full: address
    }
  }
}];

// Combine skip trace and valuation data

const lead = $('Parse Address Components').item.json;
const skipTraceResult = $('Skip Trace API').item.json;
const zillowResult = $('Get Zillow Valuation').item.json;

// Parse skip trace response (structure varies by provider)
let ownerName = '';
let phones = [];
let emails = [];

try {
  // BatchSkipTracing typical response structure
  const data = skipTraceResult.data || skipTraceResult;
  ownerName = data.owner_name || data.ownerName || '';
  phones = data.phones || data.phone_numbers || [];
  emails = data.emails || data.email_addresses || [];

  // Normalize phone format
  if (typeof phones === 'string') phones = [phones];
  if (typeof emails === 'string') emails = [emails];
} catch (e) {
  console.log('Skip trace parse error:', e);
}

// Parse Zillow valuation
let zestimate = null;
let propertyDetails = {};

try {
  const results = zillowResult.cat1?.searchResults?.mapResults || [];
  if (results.length > 0) {
    const prop = results[0];
    zestimate = prop.zestimate || prop.price;
    propertyDetails = {
      beds: prop.beds,
      baths: prop.baths,
      sqft: prop.livingArea || prop.area,
      yearBuilt: prop.yearBuilt,
      lotSize: prop.lotSize,
      homeType: prop.homeType
    };
  }
} catch (e) {
  console.log('Zillow parse error:', e);
}

return [{
  json: {
    leadId: lead.id,
    address: lead.parsedAddress.full,
    originalData: lead,
    enrichment: {
      ownerName: ownerName,
      phones: phones.slice(0, 3), // Top 3 phones
      emails: emails.slice(0, 2), // Top 2 emails
      primaryPhone: phones[0] || null,
      primaryEmail: emails[0] || null
    },
    valuation: {
      zestimate: zestimate,
      ...propertyDetails
    },
    askingPrice: lead.fields?.['Asking Price'] || lead['Asking Price'],
    equity: zestimate && lead.fields?.['Asking Price'] ? 
      zestimate - lead.fields['Asking Price'] : null
  }
}];

