// Parse AI analysis and prepare final enrichment data

const enrichment = $('Combine Enrichment Data').item.json;
const aiResponse = $input.first().json;

let analysis = {};
try {
  const content = aiResponse.choices[0].message.content;
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  analysis = {
    deal_score: 50,
    wholesale_margin_estimate: null,
    below_market_percent: null,
    estimated_arv: null,
    estimated_repairs: null,
    exit_strategy: 'wholesale',
    motivation_signals: [],
    red_flags: ['AI analysis failed'],
    questions_to_ask: ['What is your timeline for selling?', 'Are you open to creative financing?'],
    summary: 'Analysis could not be completed. Manual review recommended.',
    priority: 'medium'
  };
}

return [{
  json: {
    leadId: enrichment.leadId,
    updateFields: {
      'Owner Name': enrichment.enrichment.ownerName,
      'Owner Phone': enrichment.enrichment.primaryPhone,
      'Owner Email': enrichment.enrichment.primaryEmail,
      'All Phones': enrichment.enrichment.phones.join(', '),
      'Estimated Value': enrichment.valuation.zestimate,
      'Beds': enrichment.valuation.beds,
      'Baths': enrichment.valuation.baths,
      'Sqft': enrichment.valuation.sqft,
      'Year Built': enrichment.valuation.yearBuilt,
      'AI Score': analysis.deal_score,
      'AI Analysis': JSON.stringify(analysis, null, 2),
      'Priority': analysis.priority,
      'Exit Strategy': analysis.exit_strategy,
      'Estimated ARV': analysis.estimated_arv,
      'Estimated Repairs': analysis.estimated_repairs,
      'Status': enrichment.enrichment.primaryPhone || enrichment.enrichment.primaryEmail ? 'Ready' : 'No Contact Info'
    },
    analysis: analysis
  }
}];

